import{_ as t,o,c as a,a2 as r}from"./chunks/framework.eFe5Lsvn.js";const m=JSON.parse('{"title":"Projects and deploying","description":"","frontmatter":{},"headers":[],"relativePath":"app/projects.md","filePath":"app/projects.md"}'),s={name:"app/projects.md"};function n(d,e,c,i,p,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="projects-and-deploying" tabindex="-1">Projects and deploying <a class="header-anchor" href="#projects-and-deploying" aria-label="Permalink to &quot;Projects and deploying&quot;">​</a></h1><p>A project is a folder containing <code>project.mayhem</code> (robot, field, named commands, pose variables) and one <code>&lt;path name&gt;.mtraj</code> file per path.</p><h2 id="put-it-in-your-robot-code" tabindex="-1">Put it in your robot code <a class="header-anchor" href="#put-it-in-your-robot-code" aria-label="Permalink to &quot;Put it in your robot code&quot;">​</a></h2><p>The easiest setup is to create the project <strong>inside your robot code</strong> at <code>src/main/deploy/mayhem/</code>. Every save is then already &quot;deployed&quot;: WPILib copies the <code>deploy</code> folder to the roboRIO on the next code deploy, and MayhemLib reads <code>deploy/mayhem/&lt;name&gt;.mtraj</code> there.</p><p>If you keep the project somewhere else, set <strong>Settings → Project → Deploy folder</strong>. Generated paths are copied there automatically whenever they are saved. A brief success banner confirms each path save.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The roboRIO file system is case sensitive. The path name in your robot code must match the file name&#39;s case exactly.</p></div><h2 id="new-projects" tabindex="-1">New projects <a class="header-anchor" href="#new-projects" aria-label="Permalink to &quot;New projects&quot;">​</a></h2><p>New projects start with the 2026 REBUILT field. Click <strong>New project</strong> on the welcome screen and pick a folder, or <strong>Open project</strong> to open an existing one. The welcome screen lists recent projects.</p><h2 id="what-gets-saved" tabindex="-1">What gets saved <a class="header-anchor" href="#what-gets-saved" aria-label="Permalink to &quot;What gets saved&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Contents</th></tr></thead><tbody><tr><td><code>project.mayhem</code></td><td>Robot, field and obstacles, pose variables, fuel sim robots and settings</td></tr><tr><td><code>&lt;Name&gt;.mtraj</code></td><td>One path: its waypoints, constraints and markers (the <em>inputs</em>), and the solved trajectory (the <em>output</em>)</td></tr></tbody></table><p>A path is marked <strong>out of date</strong> when its inputs change after it was generated. Regenerate it before you deploy.</p>',11)])])}const u=t(s,[["render",n]]);export{m as __pageData,u as default};
